{"command":"python3 -c "
import csv

# Load raw data for verification
raw = {}
with open('outputs/t02_eurostat_raw.csv', 'r', newline='') as f:
    reader = csv.reader(f)
    next(reader)
    for row in reader:
        key = (row[0], row[2], row[3])
        raw[key] = row[5]

# Load pivoted data and verify
with open('outputs/t11_city_indicator_matrix.csv', 'r', newline='') as f:
    reader = csv.reader(f)
    header = next(reader)
    ind_positions = {h: i for i, h in enumerate(header) if h not in ['city_id', 'city_name', 'year']}

    errors = 0
    for row in reader:
        city_id = row[0]
        year = row[2]
        for ind_id, pos in ind_positions.items():
            pivot_val = row[pos]
            raw_val = raw.get((city_id, year, ind_id), '')
            if pivot_val != raw_val:
                print(f'Mismatch: ({city_id}, {year}, {ind_id}): pivot={repr(pivot_val)}, raw={repr(raw_val)}')
                errors += 1

if errors == 0:
    print('All values match - pivot is correct!')
else:
    print(f'{errors} mismatches found')
""}
